ccci_dpmaif.probe_body:
static int dpmaif_probe(struct platform_device *pdev)
{
#if IS_ENABLED(CONFIG_TETRIS_CCCI_HIF_RESOURCES)
	u32 version, platform, capability;
	int error;
	error = of_property_read_u32(pdev->dev.of_node, "mediatek,dpmaif-ver", &version);
	if (error)
		return error;
	error = of_property_read_u32(pdev->dev.of_node, "mediatek,plat-info", &platform);
	if (error)
		return error;
	error = of_property_read_u32(pdev->dev.of_node, "mediatek,dpmaif-cap", &capability);
	if (error)
		return error;
	if (version != 3 || platform != 6878)
		return -EOPNOTSUPP;
	return tetris_hif_supplier_probe(pdev, DPMAIF_HIF_ID,
		tetris_hif_clocks, ARRAY_SIZE(tetris_hif_clocks),
		capability & (DPMAIF_CAP_LRO | DPMAIF_CAP_2RXQ) ? DPMAIF_RXQ_NUM : 1);
#endif
	if (of_property_read_u32(pdev->dev.of_node,
			"mediatek,dpmaif-ver", &g_dpmf_ver)) {
		CCCI_ERROR_LOG(0, TAG,
			"[%s] error: not find mediatek,dpmaif-ver.\n", __func__);
		g_dpmf_ver = MAX_DPMAIF_VER;
	}

	if (g_dpmf_ver == 0 || g_dpmf_ver > MAX_DPMAIF_VER) {
		CCCI_ERROR_LOG(0, TAG,
			"[%s] error: g_dpmf_ver(%d) is invalid.\n",
			__func__, g_dpmf_ver);
		return -1;
	}

	if (of_property_read_u32(pdev->dev.of_node,
			"mediatek,plat-info", &g_plat_inf))
		g_plat_inf = DEFAULT_PLAT_INF;

	CCCI_NORMAL_LOG(0, TAG,
		"[%s] g_dpmf_ver: %u; g_plat_inf: %u\n",
		__func__, g_dpmf_ver, g_plat_inf);

	if (dpmaif_init_com(&pdev->dev))
		return -1;

	return 0;
}

